import logging

import azure.functions as func

app = func.FunctionApp()


@app.cosmos_db_trigger(arg_name="docs", connection="COSMOS_CONNECTION",
                       database_name="kb", container_name="articles",
                       lease_container_name="leases",
                       create_lease_container_if_not_exists=True,
                       lease_container_prefix="embedder-")
def embed_changed(docs: func.DocumentList) -> None:
    for doc in docs:
        if doc.get("deleted"):
            continue  # soft delete: remove the article's chunks elsewhere
        logging.info("re-embedding %s", doc["id"])

-- HNSW for cosine distance; give the build session more memory
SET maintenance_work_mem = '2GB';
CREATE INDEX chunks_embedding_hnsw ON chunks
    USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);

-- Or DiskANN on flexible server (allow-list pg_diskann first)
CREATE EXTENSION IF NOT EXISTS pg_diskann CASCADE;
CREATE INDEX chunks_embedding_diskann ON chunks
    USING diskann (embedding vector_cosine_ops);

-- More recall for one transaction only, then confirm the plan
BEGIN;
SET LOCAL hnsw.ef_search = 120;
EXPLAIN (ANALYZE, BUFFERS)
-- '[0.12, 0.05, ...]' stands for a full 1,536-value query vector
SELECT id FROM chunks ORDER BY embedding <=> '[0.12, 0.05, ...]' LIMIT 5;
COMMIT;

import json
import logging

import azure.functions as func

app = func.FunctionApp(http_auth_level=func.AuthLevel.FUNCTION)


@app.route(route="reports", methods=["POST"])
@app.service_bus_queue_output(arg_name="job", queue_name="reports",
                              connection="ServiceBusConnection")
def request_report(req: func.HttpRequest, job: func.Out[str]) -> func.HttpResponse:
    try:
        body = req.get_json()
    except ValueError:
        return func.HttpResponse("expected JSON", status_code=400)
    job.set(json.dumps({"reportId": body["reportId"]}))
    return func.HttpResponse(status_code=202)  # accepted; built in the background


@app.service_bus_queue_trigger(arg_name="msg", queue_name="reports",
                               connection="ServiceBusConnection")
def build_report(msg: func.ServiceBusMessage) -> None:
    job = json.loads(msg.get_body().decode())
    logging.info("building report %s", job["reportId"])


@app.timer_trigger(arg_name="timer", schedule="0 30 2 * * *")  # 02:30 every day
def nightly_cleanup(timer: func.TimerRequest) -> None:
    if timer.past_due:
        logging.warning("timer ran late")
